bool inside(const void* block, const std::byte* buffer, std::size_t size) {
    auto address = reinterpret_cast<std::uintptr_t>(block);
    auto begin = reinterpret_cast<std::uintptr_t>(buffer);
    return address >= begin && address < begin + size;
}

