    alignas(std::max_align_t) std::byte west[2048];
    alignas(std::max_align_t) std::byte east[2048];
    std::pmr::monotonic_buffer_resource west_arena{west, sizeof(west)};
    std::pmr::monotonic_buffer_resource east_arena{east, sizeof(east)};

    std::pmr::vector<Particle> spawned{&west_arena};
    spawned.reserve(4);
    for (int i = 0; i < 4; ++i) {
        spawned.push_back(Particle{static_cast<float>(i), 0.0f});
    }

    std::pmr::vector<Particle> live{&east_arena};
    live = std::move(spawned);

    std::pmr::vector<Particle> adopted{std::move(live)};

