class Domain final : public std::pmr::memory_resource {
public:
    Domain(std::size_t& calls, bool interchangeable) noexcept
        : calls_(&calls), interchangeable_(interchangeable) {}

private:
    void* do_allocate(std::size_t bytes, std::size_t align) override {
        ++*calls_;
        return std::pmr::new_delete_resource()->allocate(bytes, align);
    }

    void do_deallocate(void* block, std::size_t bytes, std::size_t align) override {
        std::pmr::new_delete_resource()->deallocate(block, bytes, align);
    }

    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        if (this == &other) return true;
        const auto* peer = dynamic_cast<const Domain*>(&other);
        return peer != nullptr && interchangeable_ && peer->interchangeable_;
    }

    std::size_t* calls_;
    bool interchangeable_;
};

std::size_t sink_allocations(bool interchangeable) {
    std::size_t source_calls = 0;
    std::size_t sink_calls = 0;
    Domain source_domain{source_calls, interchangeable};
    Domain sink_domain{sink_calls, interchangeable};

    std::pmr::vector<int> source{&source_domain};
    source.reserve(64);
    for (int i = 0; i < 64; ++i) source.push_back(i);

    std::pmr::vector<int> sink{&sink_domain};
    sink = std::move(source);

    return sink_calls;
}

int main() {
    std::cout << sink_allocations(true) << ' '
              << sink_allocations(false) << '\n';
}

