#include <cstddef>
#include <limits>
#include <list>
#include <new>

// A slab of same-sized blocks with a free list threaded through the dead
// ones. Reuse is the whole point: a node returned by deallocate must be the
// block handed back by the next allocate of the same size.
class NodeSlab {
public:
    NodeSlab(std::byte* data, std::size_t capacity, std::size_t block_size)
        : data_(data), capacity_(capacity), block_(block_size) {}

    std::size_t high_water() const noexcept { return used_; }

    void* take(std::size_t bytes) {
        if (bytes > block_) throw std::bad_alloc{};  // wrong size class
        if (free_ != nullptr) {                      // reuse before growth
            void* block = free_;
            free_ = *reinterpret_cast<void**>(free_);
            return block;
        }
        if (used_ + block_ > capacity_) throw std::bad_alloc{};
        void* block = data_ + used_;
        used_ += block_;
        return block;
    }

    void give_back(void* block) noexcept {
        *reinterpret_cast<void**>(block) = free_;  // the dead block is the link
        free_ = block;
    }

private:
    std::byte* data_;
    std::size_t capacity_;
    std::size_t block_;
    std::size_t used_ = 0;
    void* free_ = nullptr;
};

template<class T>
class SlabAllocator {
    template<class> friend class SlabAllocator;

public:
    using value_type = T;

    explicit SlabAllocator(NodeSlab& slab) noexcept : slab_(&slab) {}

    // Rebind: std::list asks for SlabAllocator<node>, and this is how the
    // slab pointer survives the conversion. Without it the container does
    // not compile at all.
    template<class U>
    SlabAllocator(const SlabAllocator<U>& other) noexcept : slab_(other.slab_) {}

    T* allocate(std::size_t count) {
        if (count > std::numeric_limits<std::size_t>::max() / sizeof(T)) {
            throw std::bad_array_new_length{};
        }
        return static_cast<T*>(slab_->take(count * sizeof(T)));
    }

    void deallocate(T* block, std::size_t) noexcept {
        slab_->give_back(block);  // straight onto the free list
    }

    template<class U>
    bool operator==(const SlabAllocator<U>& other) const noexcept {
        return slab_ == other.slab_;  // equal means: same free list
    }

    template<class U>
    bool operator!=(const SlabAllocator<U>& other) const noexcept {
        return !(*this == other);
    }

private:
    NodeSlab* slab_;
};

// The contract, executable: four insert/erase cycles must touch the slab's
// high-water mark only once.
bool reuses_blocks() {
    alignas(std::max_align_t) std::byte bytes[8192];
    NodeSlab slab{bytes, sizeof(bytes), 64};

    std::list<int, SlabAllocator<int>> ready{SlabAllocator<int>{slab}};

    ready.push_back(1);
    const std::size_t after_first = slab.high_water();

    for (int round = 0; round < 4; ++round) {
        ready.pop_back();
        ready.push_back(round);
    }

    return slab.high_water() == after_first;
}

#include <cstddef>
#include <limits>
#include <memory>
#include <new>
#include <type_traits>
#include <utility>
#include <vector>

class Arena {
public:
    explicit Arena(std::size_t capacity)
        : bytes_(std::make_unique<std::byte[]>(capacity)), capacity_(capacity) {}

    void* take(std::size_t bytes, std::size_t alignment) {
        void* candidate = bytes_.get() + used_;
        std::size_t space = capacity_ - used_;
        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) throw std::bad_alloc{};
        used_ = static_cast<std::byte*>(aligned) - bytes_.get() + bytes;
        return aligned;
    }

private:
    std::unique_ptr<std::byte[]> bytes_;
    std::size_t capacity_;
    std::size_t used_ = 0;
};

// Shared ownership is what earns the right to propagate. A container that
// adopts this allocator also adopts a share of the arena's lifetime, so the
// adopted buffer cannot outlive its storage.
template<class T>
class SharedArenaAllocator {
    template<class> friend class SharedArenaAllocator;

public:
    using value_type = T;

    // The promise being made: the allocator may travel with the container on
    // copy assignment, move assignment and swap.
    using propagate_on_container_copy_assignment = std::true_type;
    using propagate_on_container_move_assignment = std::true_type;
    using propagate_on_container_swap = std::true_type;

    explicit SharedArenaAllocator(std::shared_ptr<Arena> arena) noexcept
        : arena_(std::move(arena)) {}

    template<class U>
    SharedArenaAllocator(const SharedArenaAllocator<U>& other) noexcept
        : arena_(other.arena_) {}

    T* allocate(std::size_t count) {
        if (count > std::numeric_limits<std::size_t>::max() / sizeof(T)) {
            throw std::bad_array_new_length{};
        }
        return static_cast<T*>(arena_->take(count * sizeof(T), alignof(T)));
    }

    void deallocate(T*, std::size_t) noexcept {}  // reclaimed all at once

    template<class U>
    bool operator==(const SharedArenaAllocator<U>& other) const noexcept {
        return arena_ == other.arena_;  // same arena object, not merely same type
    }

    template<class U>
    bool operator!=(const SharedArenaAllocator<U>& other) const noexcept {
        return !(*this == other);
    }

private:
    std::shared_ptr<Arena> arena_;
};

struct Sample {
    float value;
};

using SampleBuffer = std::vector<Sample, SharedArenaAllocator<Sample>>;

// With POCMA true this is O(1) even across different arenas: the destination
// takes the source's allocator with the buffer, and the shared_ptr keeps the
// source arena alive for exactly as long as the destination needs it.
void hand_over(SampleBuffer& destination, SampleBuffer&& source) {
    destination = std::move(source);
}

#include <memory_resource>
#include <utility>
#include <vector>

struct Waypoint {
    double latitude;
    double longitude;
};

// Contract: never leave either route holding storage it cannot release, and
// take the O(1) path only when it is actually legal.
void hand_over(std::pmr::vector<Waypoint>& destination,
               std::pmr::vector<Waypoint>& source) {
    auto* to = destination.get_allocator().resource();
    auto* from = source.get_allocator().resource();

    if (to->is_equal(*from)) {
        // The resources promise that either may free the other's storage, so
        // exchanging buffers is valid and constant time. polymorphic_allocator
        // does not propagate on swap, and with equal allocators it does not
        // need to.
        destination.swap(source);
        source.clear();
        return;
    }

    // Unequal: swap here would be undefined behaviour, not a slower path.
    // Move assignment has a defined fallback instead - the destination
    // allocates from its own resource, moves each element across, and
    // destroys the source's. O(n), with one destination allocation.
    destination = std::move(source);
    source.clear();
}

#include <cstddef>
#include <memory>
#include <memory_resource>
#include <new>

// A scratch arena for a parser that processes one document per call. Marking
// and rewinding is what makes the same bytes serve every document: after a
// rewind the next allocation of the same size gets the same block back.
class ScratchResource final : public std::pmr::memory_resource {
public:
    ScratchResource(std::byte* data, std::size_t capacity) noexcept
        : data_(data), capacity_(capacity) {}

    std::size_t mark() const noexcept { return used_; }

    // Only valid once every object allocated after the mark is dead.
    void rewind(std::size_t point) noexcept { used_ = point; }

    std::size_t high_water() const noexcept { return high_water_; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* candidate = data_ + used_;
        std::size_t space = capacity_ - used_;

        // The alignment argument is not advisory: skipping it hands a
        // misaligned block to any element wider than a byte.
        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) {
            throw std::bad_alloc{};  // no upstream: exhaustion is an error
        }

        used_ = static_cast<std::size_t>(
                    static_cast<std::byte*>(aligned) - data_) + bytes;
        if (used_ > high_water_) high_water_ = used_;
        return aligned;
    }

    void do_deallocate(void*, std::size_t, std::size_t) override {}

    // Equality promises that either resource may release storage obtained
    // from the other. Two ScratchResources own disjoint buffers, so only
    // identity qualifies.
    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }

    std::byte* data_;
    std::size_t capacity_;
    std::size_t used_ = 0;
    std::size_t high_water_ = 0;
};

#include <cstddef>
#include <cstdint>
#include <memory_resource>
#include <new>

// Serve from a fast primary resource, fall back to a slower secondary when
// the primary is exhausted. The hard part is deallocation: every block must
// go home to the resource that produced it, and memory_resource gives you
// only the pointer, the size and the alignment to decide with.
class FallbackResource final : public std::pmr::memory_resource {
public:
    FallbackResource(std::pmr::memory_resource* primary,
                     const std::byte* primary_begin,
                     std::size_t primary_size,
                     std::pmr::memory_resource* secondary) noexcept
        : primary_(primary),
          primary_begin_(primary_begin),
          primary_size_(primary_size),
          secondary_(secondary) {}

    std::size_t fallbacks() const noexcept { return fallbacks_; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        try {
            return primary_->allocate(bytes, alignment);
        } catch (const std::bad_alloc&) {
            ++fallbacks_;
            return secondary_->allocate(bytes, alignment);
        }
    }

    void do_deallocate(
        void* block, std::size_t bytes, std::size_t alignment) override {
        // Route by provenance, not by guesswork: the primary's blocks all
        // live inside the buffer it was built over.
        if (owned_by_primary(block)) {
            primary_->deallocate(block, bytes, alignment);
        } else {
            secondary_->deallocate(block, bytes, alignment);
        }
    }

    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;  // no other object can free these blocks
    }

    bool owned_by_primary(const void* block) const noexcept {
        auto address = reinterpret_cast<std::uintptr_t>(block);
        auto begin = reinterpret_cast<std::uintptr_t>(primary_begin_);
        return address >= begin && address < begin + primary_size_;
    }

    std::pmr::memory_resource* primary_;
    const std::byte* primary_begin_;
    std::size_t primary_size_;
    std::pmr::memory_resource* secondary_;
    std::size_t fallbacks_ = 0;
};

#include <cstddef>
#include <memory_resource>
#include <string>
#include <vector>

struct Entry {
    std::pmr::string name;
    int slot;
};

// Safe to return by value: the caller names the resource, so the returned
// container's allocator points at storage the caller already owns. This is
// the fix for the "local arena, returned vector" shape - there the buffer and
// the resource both died with the frame.
std::pmr::vector<Entry> load_registry(std::pmr::memory_resource* into) {
    std::pmr::vector<Entry> entries{into};
    entries.reserve(4);
    // PMR construction propagates the resource, so each Entry's pmr::string
    // is built with `into` as well - no scoped_allocator_adaptor needed.
    entries.push_back(Entry{std::pmr::string{"noise-generator", into}, 0});
    entries.push_back(Entry{std::pmr::string{"reverb-tail", into}, 1});
    return entries;
}

class PluginHost {
public:
    PluginHost() : entries_(load_registry(&resource_)) {}

    std::size_t size() const noexcept { return entries_.size(); }

    // Deliberately absent: an accessor returning entries_ by value to a caller
    // with no resource of its own would copy into the default resource, and a
    // reference handed outside the host outlives nothing safely.

private:
    // Declaration order is the contract: members are destroyed in reverse
    // declaration order, so entries_ dies first and its final deallocate call
    // still reaches a live resource_. Swapping these two lines leaves the
    // vector's destructor with a dangling allocator.
    std::pmr::unsynchronized_pool_resource resource_;
    std::pmr::vector<Entry> entries_;
};

#include <cstddef>
#include <cstdlib>
#include <memory_resource>
#include <span>
#include <vector>

struct Body {
    float x;
    float y;
    float vx;
    float vy;
};

// A tripwire that needs no global operator new replacement: while the guard
// is armed, any allocation reaching this resource aborts.
class GuardedResource final : public std::pmr::memory_resource {
public:
    explicit GuardedResource(std::pmr::memory_resource* upstream) noexcept
        : upstream_(upstream) {}

    void arm() noexcept { armed_ = true; }
    void disarm() noexcept { armed_ = false; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        if (armed_) std::abort();  // steady state must not allocate
        return upstream_->allocate(bytes, alignment);
    }

    void do_deallocate(
        void* block, std::size_t bytes, std::size_t alignment) override {
        upstream_->deallocate(block, bytes, alignment);
    }

    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }

    std::pmr::memory_resource* upstream_;
    bool armed_ = false;
};

class World {
public:
    static constexpr std::size_t max_bodies = 4096;

    World()
        : arena_(storage_, sizeof(storage_), std::pmr::null_memory_resource()),
          guard_(&arena_),
          bodies_(&guard_) {
        bodies_.reserve(max_bodies);
        bodies_.resize(max_bodies);  // warm-up: first-touch every page
        bodies_.clear();             // keeps the capacity, drops the size
        guard_.arm();                // steady state begins
    }

    void step(std::span<const Body> incoming) {
        if (incoming.size() > max_bodies) {
            return;  // reject rather than surprise-grow
        }
        bodies_.clear();
        bodies_.insert(bodies_.end(), incoming.begin(), incoming.end());
        for (Body& body : bodies_) {
            body.x += body.vx;
            body.y += body.vy;
        }
    }

    ~World() { guard_.disarm(); }  // the destructor's deallocate is allowed

private:
    alignas(std::max_align_t) std::byte storage_[max_bodies * sizeof(Body) * 2];
    std::pmr::monotonic_buffer_resource arena_;
    GuardedResource guard_;
    std::pmr::vector<Body> bodies_;
};

#include <cstddef>
#include <memory_resource>
#include <vector>

// Counting allocations answers "how often". Peak live bytes answers "how
// much at once", which is the number a fixed buffer has to cover - and it is
// strictly larger than the final size whenever a container relocates, because
// the old and new blocks are alive at the same time.
class HighWaterResource final : public std::pmr::memory_resource {
public:
    explicit HighWaterResource(std::pmr::memory_resource* upstream) noexcept
        : upstream_(upstream) {}

    std::size_t peak() const noexcept { return peak_; }
    std::size_t live() const noexcept { return live_; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* block = upstream_->allocate(bytes, alignment);
        live_ += bytes;                       // count only after success
        if (live_ > peak_) peak_ = live_;
        return block;
    }

    void do_deallocate(
        void* block, std::size_t bytes, std::size_t alignment) override {
        live_ -= bytes;
        upstream_->deallocate(block, bytes, alignment);
    }

    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }

    std::pmr::memory_resource* upstream_;
    std::size_t live_ = 0;
    std::size_t peak_ = 0;
};

// The contract this makes testable: growth needs headroom, a reserve does not.
bool growth_peaks_above_final_size() {
    std::size_t grown_peak = 0;
    std::size_t reserved_peak = 0;

    {
        HighWaterResource audit{std::pmr::new_delete_resource()};
        std::pmr::vector<int> samples{&audit};
        for (int i = 0; i < 1'000; ++i) samples.push_back(i);
        grown_peak = audit.peak();
    }
    {
        HighWaterResource audit{std::pmr::new_delete_resource()};
        std::pmr::vector<int> samples{&audit};
        samples.reserve(1'000);
        for (int i = 0; i < 1'000; ++i) samples.push_back(i);
        reserved_peak = audit.peak();
    }

    return grown_peak > reserved_peak;
}
